import { ConfigUnsetError } from "./error.js";
function getCommonOptions(base) {
    const options = base || {};
    if (options.bucket === undefined) {
        const value = process.env["ACTIONS_GCS_CACHE_BUCKET"];
        if (!value) {
            throw new ConfigUnsetError("Config Error: no bucket value provided and ACTIONS_GCS_CACHE_BUCKET environment variable is unset");
        }
        options.bucket = value;
    }
    return options;
}
export function getUploadOptions(base) {
    return getCommonOptions(base);
}
export function getDownloadOptions(base) {
    const options = getCommonOptions(base);
    if (options.lookupOnly === undefined) {
        options.lookupOnly = false;
    }
    return options;
}
